"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { useControllableState } from "../lib/hooks";

interface TabsContextValue {
  value: string | undefined;
  setValue: (value: string) => void;
  variant: "line" | "pill" | "solid";
  baseId: string;
}

const TabsContext = React.createContext<TabsContextValue | null>(null);

function useTabs(component: string): TabsContextValue {
  const context = React.useContext(TabsContext);
  if (!context) throw new Error(`<${component}> moet binnen <Tabs> staan.`);
  return context;
}

export interface TabsProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  variant?: "line" | "pill" | "solid";
}

/** Tabs — tabbladen met pijltjesnavigatie (line, pill of solid). */
export const Tabs = React.forwardRef<HTMLDivElement, TabsProps>(function Tabs(
  { value, defaultValue, onValueChange, variant = "line", className, children, ...rest },
  ref
) {
  const [current, setCurrent] = useControllableState<string | undefined>({
    value,
    defaultValue,
    onChange: (next) => next !== undefined && onValueChange?.(next),
  });
  const baseId = React.useId();

  return (
    <TabsContext.Provider value={{ value: current, setValue: setCurrent, variant, baseId }}>
      <div ref={ref} className={cn("pxui-tabs", className)} {...rest}>
        {children}
      </div>
    </TabsContext.Provider>
  );
});

export const TabsList = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  function TabsList({ className, children, onKeyDown, ...rest }, ref) {
    const { variant } = useTabs("TabsList");
    const inner = React.useRef<HTMLDivElement | null>(null);

    return (
      <div
        ref={(node) => {
          inner.current = node;
          if (typeof ref === "function") ref(node as HTMLDivElement);
          else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
        }}
        role="tablist"
        className={cn("pxui-tabs-list", `pxui-tabs-list-${variant}`, className)}
        onKeyDown={(event) => {
          onKeyDown?.(event);
          const tabs = Array.from(
            inner.current?.querySelectorAll<HTMLElement>('[role="tab"]:not([disabled])') ?? []
          );
          const index = tabs.indexOf(document.activeElement as HTMLElement);
          if (index === -1) return;
          if (event.key === "ArrowRight") {
            event.preventDefault();
            tabs[(index + 1) % tabs.length].focus();
            tabs[(index + 1) % tabs.length].click();
          } else if (event.key === "ArrowLeft") {
            event.preventDefault();
            const previous = tabs[(index - 1 + tabs.length) % tabs.length];
            previous.focus();
            previous.click();
          }
        }}
        {...rest}
      >
        {children}
      </div>
    );
  }
);

export interface TabsTriggerProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  value: string;
  icon?: React.ReactNode;
  /** Telling of status rechts van het label. */
  badge?: React.ReactNode;
}

export const TabsTrigger = React.forwardRef<HTMLButtonElement, TabsTriggerProps>(function TabsTrigger(
  { value, icon, badge, className, children, disabled, ...rest },
  ref
) {
  const { value: current, setValue, baseId } = useTabs("TabsTrigger");
  const active = current === value;

  return (
    <button
      ref={ref}
      type="button"
      role="tab"
      id={`${baseId}-tab-${value}`}
      aria-controls={`${baseId}-panel-${value}`}
      aria-selected={active}
      tabIndex={active ? 0 : -1}
      disabled={disabled}
      data-state={active ? "active" : "inactive"}
      className={cn("pxui-tab", className)}
      onClick={() => setValue(value)}
      {...rest}
    >
      {icon && <span className="pxui-tab-icon">{icon}</span>}
      {children}
      {badge !== undefined && <span className="pxui-tab-badge">{badge}</span>}
    </button>
  );
});

export interface TabsContentProps extends React.HTMLAttributes<HTMLDivElement> {
  value: string;
  /** Houdt de inhoud gemonteerd wanneer het tabblad niet actief is. */
  keepMounted?: boolean;
}

export const TabsContent = React.forwardRef<HTMLDivElement, TabsContentProps>(function TabsContent(
  { value, keepMounted, className, children, ...rest },
  ref
) {
  const { value: current, baseId } = useTabs("TabsContent");
  const active = current === value;
  if (!active && !keepMounted) return null;

  return (
    <div
      ref={ref}
      role="tabpanel"
      id={`${baseId}-panel-${value}`}
      aria-labelledby={`${baseId}-tab-${value}`}
      hidden={!active || undefined}
      tabIndex={0}
      className={cn("pxui-tabs-content", className)}
      {...rest}
    >
      {children}
    </div>
  );
});

/* ============================ Tabs ============================ */
.pxui-tabs { display: flex; flex-direction: column; min-width: 0; }

.pxui-tabs-list { display: flex; gap: 4px; min-width: 0; }
.pxui-tabs-list-line { border-bottom: 1px solid var(--border); margin-bottom: 20px; overflow-x: auto; }
.pxui-tabs-list-pill {
  background: var(--surface-3); border-radius: var(--r-sm);
  padding: 3px; gap: 2px; align-self: flex-start; margin-bottom: 18px;
}
.pxui-tabs-list-solid {
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--r-md); padding: 4px; gap: 3px;
  align-self: flex-start; margin-bottom: 18px; box-shadow: var(--sh-xs);
}

.pxui-tab {
  display: inline-flex; align-items: center; gap: 8px;
  border: none; background: transparent; cursor: pointer;
  font: inherit; font-size: var(--fs-base); font-weight: 600;
  color: var(--text-3); white-space: nowrap;
  transition: color var(--dur-fast), background var(--dur-fast), border-color var(--dur-fast);
}
.pxui-tab:focus-visible { outline: none; box-shadow: var(--ring); border-radius: var(--r-xs); }
.pxui-tab:disabled { opacity: .45; cursor: not-allowed; }
.pxui-tab-icon { display: inline-flex; }
.pxui-tab-icon svg { width: 16px; height: 16px; }
.pxui-tab-badge {
  display: inline-grid; place-items: center; min-width: 19px; height: 19px;
  padding: 0 6px; border-radius: var(--r-full);
  background: var(--surface-3); color: var(--text-2);
  font-size: 11px; font-weight: 700;
}

.pxui-tabs-list-line .pxui-tab {
  padding: calc(10px * var(--density)) 14px; border-bottom: 2px solid transparent; margin-bottom: -1px;
}
.pxui-tabs-list-line .pxui-tab:hover:not(:disabled) { color: var(--text); }
.pxui-tabs-list-line .pxui-tab[data-state="active"] { color: var(--accent-active); border-bottom-color: var(--accent); }
.pxui-tabs-list-line .pxui-tab[data-state="active"] .pxui-tab-badge { background: var(--accent-tint-2); color: var(--accent-active); }

.pxui-tabs-list-pill .pxui-tab,
.pxui-tabs-list-solid .pxui-tab {
  height: calc(32px * var(--density)); padding: 0 13px; border-radius: var(--r-xs); font-size: 13px;
}
.pxui-tabs-list-pill .pxui-tab:hover:not(:disabled),
.pxui-tabs-list-solid .pxui-tab:hover:not(:disabled) { color: var(--text); }
.pxui-tabs-list-pill .pxui-tab[data-state="active"] {
  background: var(--surface); color: var(--text); box-shadow: var(--sh-xs);
}
.pxui-tabs-list-solid .pxui-tab[data-state="active"] {
  background: var(--accent-tint); color: var(--accent-active);
}

.pxui-tabs-content:focus-visible { outline: none; }
